<template><el-card><h3>照片交付</h3><el-button @click="load">刷新</el-button><el-table :data="items"><el-table-column prop="id" label="批次"/><el-table-column prop="status" label="状态"/><el-table-column prop="at" label="时间"/><el-table-column label="操作"><template #default="{row}"><el-link v-if="row.status==='prepared'" :href="'/api/v1/deliveries/'+row.id+'/download'" target="_blank">下载</el-link><el-button v-if="row.status==='prepared'" size="small" @click="act(row,'confirm')">确认交付</el-button><el-button v-if="row.status==='prepared'" size="small" type="danger" @click="act(row,'cancel')">取消</el-button></template></el-table-column></el-table></el-card></template><script setup>import{ref,onMounted}from"vue";const items=ref([]);async function load(){items.value=await(await fetch('/api/v1/deliveries')).json()}async function act(x,a){await fetch('/api/v1/deliveries/'+x.id+'/'+a,{method:'POST'});load()}onMounted(load)</script>